static class C
{
    static void M1(this int x, ref readonly int y) { }
    static void M2(this ref readonly int x, ref readonly int y) { }
    static void M3()
    {
        var x = 1;
        x.M1(in x);
        x.M1(x);
        M1(x, in x);
        M1(x, x);
        x.M2(in x);
        x.M2(x);
        M2(x, in x);
        M2(x, x);
        M2(in x, in x);
        M2(in x, x);
    }
}

